# ==============================================================================
# --- 4. Filter module gene lists according to object features ---
# ==============================================================================

filter_module_genes <- function(gene_list, object) {
  
  filtered <- lapply(gene_list, function(x) {
    x[x %in% rownames(object)]
  })
  
  missing_genes <- lapply(names(gene_list), function(module_name) {
    setdiff(gene_list[[module_name]], filtered[[module_name]])
  })
  names(missing_genes) <- names(gene_list)
  
  for (module_name in names(missing_genes)) {
    if (length(missing_genes[[module_name]]) > 0) {
      warning(
        "Missing genes in module '", module_name, "': ",
        paste(missing_genes[[module_name]], collapse = ", ")
      )
    }
  }
  
  filtered <- filtered[lengths(filtered) > 0]
  return(filtered)
}

functional_modules_filtered <- filter_module_genes(
  gene_list = functional_modules,
  object = seu_int_rpca
)


# ==============================================================================
# --- 5. Calculate module scores ---
# ==============================================================================

set.seed(1)

score_prefix <- "HKST_ModuleScore_"

seu_int_rpca <- AddModuleScore(
  object = seu_int_rpca,
  features = functional_modules_filtered,
  name = score_prefix,
  assay = "SCT",
  seed = 1
)

module_score_mapping <- tibble(
  module = names(functional_modules_filtered),
  score_column = paste0(score_prefix, seq_along(functional_modules_filtered))
)

print(module_score_mapping)


# ==============================================================================
# --- 6. Prepare macrophage-related subset ---
# ==============================================================================

macrophage_groups <- c(
  "Mac (Homeostatic)",
  "Mac (Infection-associated)",
  "Outer E-Mac",
  "Inner E-Mac"
)

macrophage_groups_present <- intersect(
  macrophage_groups,
  levels(Idents(seu_int_rpca))
)

missing_macrophage_groups <- setdiff(
  macrophage_groups,
  macrophage_groups_present
)

if (length(missing_macrophage_groups) > 0) {
  warning(
    "The following macrophage-related groups are missing: ",
    paste(missing_macrophage_groups, collapse = ", ")
  )
}

object_sub <- subset(
  x = seu_int_rpca,
  cells = WhichCells(seu_int_rpca, idents = macrophage_groups_present)
)

message("Macrophage-related subset:")
print(table(Idents(object_sub), object_sub$orig.ident))


# ==============================================================================
# --- 7. Helper functions for module score visualization ---
# ==============================================================================

make_score_dataframe <- function(object, score_column) {
  
  score_df <- FetchData(
    object = object,
    vars = score_column
  ) %>%
    tibble::rownames_to_column("cell_id") %>%
    mutate(
      ident = as.character(Idents(object)[cell_id]),
      score = .data[[score_column]]
    )
  
  score_df$ident <- factor(
    score_df$ident,
    levels = levels(Idents(object))
  )
  
  return(score_df)
}


get_valid_comparisons <- function(comparisons, available_groups) {
  
  valid <- lapply(comparisons, function(x) {
    if (all(x %in% available_groups)) {
      return(x)
    } else {
      return(NULL)
    }
  })
  
  valid <- valid[!sapply(valid, is.null)]
  return(valid)
}


make_spatial_score_plot <- function(object, score_column, module_name) {
  
  p <- SpatialFeaturePlot(
    object = object,
    features = score_column,
    image.alpha = 0,
    pt.size.factor = 4,
    ncol = 2,
    crop = FALSE
  ) &
    scale_fill_gradientn(
      colors = color_wp,
      limits = c(0, NA),
      oob = scales::squish
    ) &
    ggtitle(module_name)
  
  return(p)
}


make_violin_score_plot <- function(object, score_column, module_name) {
  
  plot_data <- make_score_dataframe(
    object = object,
    score_column = score_column
  )
  
  comparisons <- list(
    c("Outer E-Mac", "Mac (Homeostatic)"),
    c("Inner E-Mac", "Mac (Infection-associated)")
  )
  
  comparisons <- get_valid_comparisons(
    comparisons = comparisons,
    available_groups = unique(as.character(plot_data$ident))
  )
  
  p <- ggplot(
    plot_data,
    aes(x = ident, y = score, fill = ident)
  ) +
    geom_violin(
      trim = FALSE,
      scale = "width",
      alpha = 0.8
    ) +
    geom_jitter(
      shape = 16,
      position = position_jitter(width = 0.15),
      size = 0.5,
      alpha = 0.4
    ) +
    scale_fill_manual(values = cluster_colors) +
    theme_classic(base_size = 14) +
    theme(
      axis.text.x = element_text(
        angle = 45,
        hjust = 1,
        size = 12,
        face = "bold"
      ),
      axis.text.y = element_text(size = 12),
      axis.title = element_text(size = 14, face = "bold"),
      plot.title = element_text(size = 16, face = "bold", hjust = 0.5),
      legend.position = "none"
    ) +
    labs(
      title = paste0(module_name, " Signature Score"),
      x = "Spatial domain",
      y = "Signature score"
    )
  
  if (length(comparisons) > 0) {
    y_max <- max(plot_data$score, na.rm = TRUE)
    label_y <- seq(
      from = y_max * 1.05,
      by = y_max * 0.10,
      length.out = length(comparisons)
    )
    
    p <- p +
      stat_compare_means(
        comparisons = comparisons,
        method = "wilcox.test",
        label = "p.signif",
        label.y = label_y,
        size = 5
      ) +
      coord_cartesian(
        ylim = c(NA, max(label_y, na.rm = TRUE) * 1.10)
      )
  }
  
  return(p)
}


make_raincloud_score_plot <- function(object, score_column, module_name) {
  
  plot_data <- make_score_dataframe(
    object = object,
    score_column = score_column
  )
  
  comparisons <- list(
    c("Outer E-Mac", "Mac (Homeostatic)"),
    c("Inner E-Mac", "Mac (Infection-associated)")
  )
  
  comparisons <- get_valid_comparisons(
    comparisons = comparisons,
    available_groups = unique(as.character(plot_data$ident))
  )
  
  p <- ggplot(
    plot_data,
    aes(x = ident, y = score, fill = ident)
  ) +
    geom_half_violin(
      side = "r",
      trim = FALSE,
      scale = "width",
      alpha = 0.7
    ) +
    geom_half_boxplot(
      side = "r",
      width = 0.2,
      outlier.shape = 16,
      outlier.size = 0,
      alpha = 0.3
    ) +
    geom_half_point(
      side = "l",
      width = 0.2,
      size = 0.6,
      alpha = 0.3
    ) +
    scale_fill_manual(values = cluster_colors) +
    theme_classic(base_size = 14) +
    theme(
      axis.text.x = element_text(size = 12, face = "bold"),
      axis.text.y = element_text(size = 12),
      axis.title = element_text(size = 14, face = "bold"),
      plot.title = element_text(size = 16, face = "bold", hjust = 0.5),
      legend.position = "none"
    ) +
    labs(
      title = paste0(module_name, " Score"),
      x = "Spatial domain",
      y = "Score"
    )
  
  if (length(comparisons) > 0) {
    y_max <- max(plot_data$score, na.rm = TRUE)
    label_y <- seq(
      from = y_max * 1.05,
      by = y_max * 0.12,
      length.out = length(comparisons)
    )
    
    p <- p +
      stat_compare_means(
        comparisons = comparisons,
        method = "wilcox.test",
        label = "p.signif",
        label.y = label_y,
        size = 6
      ) +
      coord_cartesian(
        ylim = c(NA, max(label_y, na.rm = TRUE) * 1.15),
        clip = "off"
      )
  }
  
  return(p)
}


# ==============================================================================
# --- 8. Generate module score plots ---
# ==============================================================================

module_score_plots <- list()

for (i in seq_len(nrow(module_score_mapping))) {
  
  module_name <- module_score_mapping$module[i]
  score_column <- module_score_mapping$score_column[i]
  
  message("Generating plots for module: ", module_name)
  
  module_score_plots[[module_name]] <- list(
    spatial_score = make_spatial_score_plot(
      object = seu_int_rpca,
      score_column = score_column,
      module_name = module_name
    ),
    
    violin_all_domains = make_violin_score_plot(
      object = seu_int_rpca,
      score_column = score_column,
      module_name = module_name
    ),
    
    raincloud_macrophage_domains = make_raincloud_score_plot(
      object = object_sub,
      score_column = score_column,
      module_name = module_name
    )
  )
}


# Example: print one module.
print(module_score_plots[["Cell Junctions"]]$spatial_score)
print(module_score_plots[["Cell Junctions"]]$raincloud_macrophage_domains)


